code='''def transform(grid):
    n, m = len(grid), len(grid[0])
    track = {}
    for r in range(n):
        for c in range(m):
            if grid[r][c]:
                d = c-r
                if d in track and track[d] != grid[r][c]:
                    raise ValueError("inconsistent diagonal")
                track[d] = grid[r][c]
    period = next(p for p in range(1, n+m+1)
                  if all(a % p != b % p or track[a] == track[b]
                         for a in track for b in track))
    residues = {d % period: color for d, color in track.items()}
    colors = list(dict.fromkeys(track[d] for d in sorted(track)))
    # Fill any unrepresented residues in the recurring color cycle.
    for k in range(period):
        if k not in residues:
            residues[k] = colors[len(residues) % len(colors)]
    return [[residues[(c-r) % period] for c in range(m)] for r in range(n)]
'''
